  const stateDir = path.join(work, "op-state");
  fs.mkdirSync(stateDir, { recursive: true });
  let toolStep = 0;
  const pressureGateway = await startGateway((_n, body) => {
    if (!body?.tools) return { kind: "text", content: "Recorded marker findings." };
    toolStep++;
